test("opening balances scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  await ui.setSetting(pg_uma, "clerk-limit", "1.50");
  await ui.setSetting(pg_uma, "terms", "7");
  await ui.setSetting(pg_uma, "late-pct", "10.00");
  await ui.setSetting(pg_uma, "terms-C", "20");
  await ui.setSetting(pg_uma, "cap", "2.00");
  await ui.setSetting(pg_uma, "perm-settle", "clerk");
  await ui.setSetting(pg_uma, "grace-C", "5");
  await ui.setSetting(pg_uma, "proof-threshold-B", "0.50");
  expect(await ui.addVoidReason(pg_uma, "late")).toBe(true);
  expect(await ui.addVoidReason(pg_uma, "error")).toBe(true);
  await ui.loadSheet(pg_uma, `${sheet}-p`);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "20.00"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B"}));
  const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "10.25"}));
  expect(await ui.claimAction(pg_uma, c_cam_0, "open")).toBe(true);
  await ui.loadSheet(pg_uma, sheet);
  await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
  expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "0.04", "note": "tpl"})).toBe(true);
  await ui.setSetting(pg_uma, "pot", "7.77");
  expect(await ui.setSettingDated(pg_uma, "rounding", "half-even", "2026-03-01", "half-even")).toBe(true);
  await ui.setSetting(pg_uma, "review-sla", "5");
  await ui.setSetting(pg_uma, "escalate-after", "1");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00", "from": "2026-03-10", "to": "2026-03-12"})).toBe(true);
  expect(await ui.generatePeriods(pg_uma, "2026-02-01", "2026-04-30")).toBe(3);
  expect(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A", "contact": "ADA@X", "tags": "a"})).toBeNull();
  expect(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A", "terms": "20", "tags": "c"})).toBeNull();
  const p_dot = ui.must(await ui.addPerson(pg_uma, {"name": "Dot", "grade": "A"}));
  expect(await ui.editPerson(pg_uma, p_dot, {"grade": "B", "gradeFrom": "2026-02-10"})).toBe(true);
  const c_dot_0 = ui.must(await ui.claimFromTemplate(pg_uma, p_dot, "T1"));
  await ui.sortBy(pg_uma, "added");
  expect(await ui.claimAction(pg_uma, c_dot_0, "open")).toBe(true);
  expect(await ui.generatePeriods(pg_uma, "2026-01-15", "2026-02-20")).toBe(1);
  expect(await ui.generatePeriods(pg_uma, "2026-01-15", "2026-02-20")).toBe(0);
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("person-row-" + p_dot).getByTestId("person-claimed")).toHaveText("0.04");
  await expect(pg_uma.getByTestId("person-row-" + p_dot).getByTestId("person-due-total")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_dot_0).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_dot_0).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_uma.getByTestId("claim-row-" + c_dot_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("rollup-claimed-total")).toHaveText("0.04");
  await expect(pg_uma.getByTestId("rollup-due-total")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("rollup-overdue-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("rollup-overdue-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-settled-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("rollup-open-total")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("bulk-settle-batch")).toHaveText("");
  await expect(pg_uma.getByTestId("rollup-cut-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("header-people-count")).toHaveText("1");
  await expect(pg_uma.getByTestId("header-claims-DRAFT-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-OPEN-count")).toHaveText("1");
