package net.officefloor.hq.app.period;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.FetchType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.Map;

/**
 * A period on a sheet: a name unique on the sheet, and a from and to date, both inclusive. Once closed or
 * soft-closed, its due-total is the one fixed then; claims due by a date inside a soft-closed one can still change.
 */
@Entity
@Table(name = "period")
public class Period {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "from_date", nullable = false)
    private LocalDate fromDate;

    @Column(name = "to_date", nullable = false)
    private LocalDate toDate;

    @Column(name = "closed", nullable = false)
    private boolean closed;

    /** Whether the period is soft-closed: its figures are fixed, but claims due by a date inside it can still change. */
    @Column(name = "soft_closed", nullable = false)
    private boolean softClosed;

    /** The most OPEN or PENDING claims a person may have in the period; null for no cap. */
    @Column(name = "claim_cap")
    private Integer cap;

    /** The due-total fixed when the period was closed or soft-closed; null while it is open. */
    @Column(name = "closed_total", precision = 14, scale = 2)
    private BigDecimal closedTotal;

    /** Per person id, the person's due-total fixed when the period was closed; empty while it is open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_total", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "total", nullable = false, precision = 14, scale = 2)
    private Map<Long, BigDecimal> personTotals = new HashMap<>();

    /** Per person id, the person's carried figure fixed when the period was closed; empty while it is open. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_carried", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "carried", nullable = false, precision = 14, scale = 2)
    private Map<Long, BigDecimal> personCarried = new HashMap<>();

    protected Period() {
    }

    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate) {
        this.sheetId = sheetId;
        this.name = name;
        this.fromDate = fromDate;
        this.toDate = toDate;
    }

    public Period(String sheetId, String name, LocalDate fromDate, LocalDate toDate, Integer cap) {
        this(sheetId, name, fromDate, toDate);
        this.cap = cap;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public LocalDate getFromDate() {
        return fromDate;
    }

    public LocalDate getToDate() {
        return toDate;
    }

    /** The most OPEN or PENDING claims a person may have in the period; null for no cap. */
    public Integer getCap() {
        return cap;
    }

    public boolean isClosed() {
        return closed;
    }

    public boolean isSoftClosed() {
        return softClosed;
    }

    /** Whether the period's figures are fixed: it is closed or soft-closed. */
    public boolean isFixed() {
        return closed || softClosed;
    }

    public BigDecimal getClosedTotal() {
        return closedTotal;
    }

    public Map<Long, BigDecimal> getPersonTotals() {
        return Map.copyOf(personTotals);
    }

    public Map<Long, BigDecimal> getPersonCarried() {
        return Map.copyOf(personCarried);
    }

    /** Close the period, fixing each person's due-total for it and its own, their sum. */
    public void close(Map<Long, BigDecimal> personTotals) {
        close(personTotals, Map.of(), false);
    }

    /**
     * Close the period, or soft-close it, fixing each person's due-total and carried figure for it and its own
     * due-total, their sum. A soft-closed period still takes changes to the claims due by a date inside it.
     */
    public void close(Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried, boolean soft) {
        this.closed = !soft;
        this.softClosed = soft;
        this.personTotals.clear();
        this.personTotals.putAll(personTotals);
        this.personCarried.clear();
        this.personCarried.putAll(personCarried);
        this.closedTotal = personTotals.values().stream().reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    /** Reopen the period: its due-total and carried figures are live again. */
    public void reopen() {
        this.closed = false;
        this.softClosed = false;
        this.closedTotal = null;
        this.personTotals.clear();
        this.personCarried.clear();
    }

    /** Whether the date falls in the period, its from and to date included. */
    public boolean contains(LocalDate date) {
        return !date.isBefore(fromDate) && !date.isAfter(toDate);
    }

    /** Whether the period shares a date with the one from {@code from} to {@code to}. */
    public boolean overlaps(LocalDate from, LocalDate to) {
        return !from.isAfter(toDate) && !to.isBefore(fromDate);
    }
}
package net.officefloor.hq.app.period;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** The periods on a sheet, earliest first. The signed-in user's name comes in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/periods")
@Validated
public class PeriodController {

    /**
     * A period as shown, whether it is closed or soft-closed; once either, with the due-total fixed then (null
     * while open), per person id the person's due-total fixed then and their carried figure fixed then (each
     * empty while open); and the fiscal year
     * (FY and a year) its from-date falls in.
     */
    public record PeriodView(long id, String name, LocalDate from, LocalDate to, boolean closed, boolean softClosed,
            String closedTotal, Map<Long, String> personTotals, String fy, Integer cap,
            Map<Long, String> personCarried) {

        static PeriodView of(Period period, int fiscalStartMonth) {
            Map<Long, String> personTotals = new TreeMap<>();
            period.getPersonTotals().forEach((id, t) -> personTotals.put(id, t.setScale(2, RoundingMode.HALF_UP).toPlainString()));
            Map<Long, String> personCarried = new TreeMap<>();
            period.getPersonCarried().forEach((id, t) -> personCarried.put(id, t.setScale(2, RoundingMode.HALF_UP).toPlainString()));
            return new PeriodView(period.getId(), period.getName(), period.getFromDate(), period.getToDate(),
                    period.isClosed(), period.isSoftClosed(), period.getClosedTotal() == null ? null
                            : period.getClosedTotal().setScale(2, RoundingMode.HALF_UP).toPlainString(),
                    personTotals, PeriodService.fiscalYear(period.getFromDate(), fiscalStartMonth), period.getCap(),
                    personCarried);
        }
    }

    /** A name, a from and to date, both inclusive, and the most OPEN or PENDING claims a person may have in it (null for none). */
    public record PeriodForm(@NotBlank @Size(max = 100) String name, @NotNull LocalDate from, @NotNull LocalDate to,
            Integer cap) {
    }

    public record Refusal(String message) {
    }

    private final PeriodService service;

    public PeriodController(PeriodService service) {
        this.service = service;
    }

    @GetMapping
    public List<PeriodView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        String sheet = sheetId.trim();
        return views(sheet, service.list(sheet));
    }

    @PostMapping
    public PeriodView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank String user, @Valid @RequestBody PeriodForm form) {
        String sheet = sheetId.trim();
        return view(sheet, service.add(sheet, user.trim(), form.name().trim(), form.from(), form.to(), form.cap()));
    }

    /** A from and to date: one period per calendar month from the from-date's month to the to-date's. */
    public record GenerateForm(@NotNull LocalDate from, @NotNull LocalDate to) {
    }

    @PostMapping("/generate")
    public List<PeriodView> generate(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank String user, @Valid @RequestBody GenerateForm form) {
        String sheet = sheetId.trim();
        return views(sheet, service.generate(sheet, user.trim(), form.from(), form.to()));
    }

    /** A calendar year: the twelve monthly periods of the fiscal year whose first day falls in it. */
    public record GenerateFiscalYearForm(@NotNull @Min(1) @Max(9999) Integer year) {
    }

    @PostMapping("/generate-fy")
    public List<PeriodView> generateFiscalYear(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank String user, @Valid @RequestBody GenerateFiscalYearForm form) {
        String sheet = sheetId.trim();
        return views(sheet, service.generateFiscalYear(sheet, user.trim(), form.year()));
    }

    private PeriodView view(String sheet, Period period) {
        return PeriodView.of(period, service.fiscalStartMonth(sheet));
    }

    private List<PeriodView> views(String sheet, List<Period> periods) {
        int fiscalStartMonth = service.fiscalStartMonth(sheet);
        return periods.stream().map(p -> PeriodView.of(p, fiscalStartMonth)).toList();
    }

    @PostMapping("/{periodId}/close")
    public PeriodView close(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long periodId,
            @RequestHeader("X-User") @NotBlank String user) {
        String sheet = sheetId.trim();
        return view(sheet, service.close(sheet, user.trim(), periodId));
    }

    @PostMapping("/{periodId}/soft-close")
    public PeriodView softClose(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long periodId,
            @RequestHeader("X-User") @NotBlank String user) {
        String sheet = sheetId.trim();
        return view(sheet, service.softClose(sheet, user.trim(), periodId));
    }

    @PostMapping("/{periodId}/reopen")
    public PeriodView reopen(@PathVariable @NotBlank @Size(max = 100) String sheetId, @PathVariable long periodId,
            @RequestHeader("X-User") @NotBlank String user) {
        String sheet = sheetId.trim();
        return view(sheet, service.reopen(sheet, user.trim(), periodId));
    }

    @ExceptionHandler(PeriodRefused.class)
    public ResponseEntity<Refusal> refused(PeriodRefused e) {
        return ResponseEntity.status(HttpStatus.CONFLICT).body(new Refusal(e.getMessage()));
    }

    /** Another user added a period with the same name at the same moment: this one is refused. */
    @ExceptionHandler(DataIntegrityViolationException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public void nameTaken() {
    }
}
    /**
     * Generate the twelve monthly periods of the fiscal year whose first day falls in the given calendar year,
     * from the sheet's fiscal start month on, exactly as {@link #generate} does. Returns the periods made,
     * earliest first.
     */
    @Transactional
    public List<Period> generateFiscalYear(String sheetId, String user, int year) {
        sheets.load(sheetId, user);
        YearMonth first = YearMonth.of(year, fiscalStartMonth(sheetId));
        return generate(sheetId, user, first.atDay(1), first.plusMonths(11).atEndOfMonth());
    }

    /**
     * Close a period, fixing each person's due-total and carried figure for it (see {@link #carried}), for every person on the sheet, and its own, their sum: the due figures of the claims due by a date inside it that counted (OPEN, PENDING and SETTLED,
     * but not an unbound OPEN claim dated within a hold of its person, nor a deferred one) at the end of its last day,
     * see {@link Dues#countsAsOf}, added up per person. A soft-closed period is closed with its figures fixed
     * afresh. Refused when it is already closed, or for a role the sheet's
     * permission matrix does not allow to close. Takes turns with claim changes on the
     * sheet, so the total fixed is the one the claims had at that moment.
     */
    @Transactional
    public Period close(String sheetId, String user, long periodId) {
        sheetRows.lockById(sheetId);
        Period period = periods.findByIdAndSheetId(periodId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period"));
        if (!access.allows(sheetId, user, Permission.CLOSE)) {
            throw new PeriodRefused("Your role may not close a period on this sheet.");
        }
        if (period.isClosed()) {
            throw new PeriodRefused("The period is already closed.");
        }
        fix(sheetId, user, period, false, false);
        return period;
    }

    /**
     * Soft-close an open period: its figures are fixed as a close fixes them, but claims due by a date inside it can
     * still be added, edited, opened, settled and voided. Refused when it is already closed or soft-closed, or
     * for a role the sheet's permission matrix does not allow to close.
     */
    @Transactional
    public Period softClose(String sheetId, String user, long periodId) {
        sheetRows.lockById(sheetId);
        Period period = periods.findByIdAndSheetId(periodId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period"));
        if (!access.allows(sheetId, user, Permission.CLOSE)) {
            throw new PeriodRefused("Your role may not close a period on this sheet.");
        }
        if (period.isClosed()) {
            throw new PeriodRefused("The period is already closed.");
        }
        if (period.isSoftClosed()) {
            throw new PeriodRefused("The period is already soft-closed.");
        }
        fix(sheetId, user, period, false, true);
        return period;
    }

    /**
     * When the sheet's today is changed and it has grace days, close every open period (neither closed nor
     * soft-closed) whose to-date plus the grace days is before the new today, in order of their to-dates, each as a close by hand would.
     */
    @EventListener
    @Transactional
    public void on(TodayChanged e) {
        Integer grace = sheets.graceDays(e.sheetId());
        if (grace == null) {
            return;
        }
        sheetRows.lockById(e.sheetId());
        list(e.sheetId()).stream()
                .filter(p -> !p.isFixed() && p.getToDate().plusDays(grace).isBefore(e.today()))
                .sorted(Comparator.comparing(Period::getToDate))
                .forEach(p -> fix(e.sheetId(), e.user(), p, true, false));
    }

    /**
     * Each person's carried figure for the period, for every person on the sheet: the due figures as they stand of
     * their claims that count on the sheet's today (neither left out by a hold or retirement nor deferred, see
     * {@link Dues#counts}) due by a date inside a period ending before it starts and still OPEN or PENDING at the end
     * of its last day, by the status log, added up per person.
     */
    private Map<Long, BigDecimal> carried(String sheetId, Period period, Map<Long, Person> byId, RateTable table) {
        List<Period> all = list(sheetId);
        Map<Long, BigDecimal> carried = new HashMap<>();
        byId.keySet().forEach(id -> carried.put(id, BigDecimal.ZERO.setScale(2)));
        claims.findBySheetIdOrderByIdDesc(sheetId).stream()
                .filter(c -> byId.containsKey(c.getPersonId()))
                .filter(c -> all.stream().anyMatch(home -> home.contains(c.getDueBy())
                        && home.getToDate().isBefore(period.getFromDate())))
                .filter(c -> c.getDeferredUntil() == null || !table.today().isBefore(c.getDeferredUntil()))
                .filter(c -> Dues.countsAsOf(c, byId.get(c.getPersonId()).leaves(), table.today(), period.getToDate()))
                .filter(c -> {
                    ClaimStatus then = Dues.statusAsOf(c, period.getToDate());
                    return then == ClaimStatus.OPEN || then == ClaimStatus.PENDING;
                })
                .forEach(c -> {
                    BigDecimal due = Dues.figure(c, byId.get(c.getPersonId())::gradeOn, table);
                    if (due != null) {
                        carried.merge(c.getPersonId(), due, BigDecimal::add);
                    }
                });
        carried.replaceAll((id, t) -> t.setScale(2, RoundingMode.HALF_UP));
        return carried;
    }

    /** Fix the period's due-totals and carried figures as of the end of its last day and close it, or soft-close it. */
    private void fix(String sheetId, String user, Period period, boolean auto, boolean soft) {
        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, p -> p));
        RateTable table = rates.table(sheetId);
        Map<Long, BigDecimal> totals = new HashMap<>();
        byId.keySet().forEach(id -> totals.put(id, BigDecimal.ZERO.setScale(2)));
        claims.findBySheetIdOrderByIdDesc(sheetId).stream()
                .filter(c -> period.contains(c.getDueBy())
                        && Dues.countsAsOf(c, byId.get(c.getPersonId()).leaves(), table.today(), period.getToDate()))
                .forEach(c -> {
                    BigDecimal due = Dues.figure(c, byId.get(c.getPersonId())::gradeOn, table);
                    if (due != null) {
                        totals.merge(c.getPersonId(), due, BigDecimal::add);
                    }
                });
        totals.replaceAll((id, t) -> t.setScale(2, RoundingMode.HALF_UP));
        period.close(totals, carried(sheetId, period, byId, table), soft);
        BigDecimal total = period.getClosedTotal().setScale(2, RoundingMode.HALF_UP);
        periods.flush();
        events.publishEvent(new PeriodClosed(sheetId, user, period.getName(), total, auto, soft));
    }

    /**
     * Reopen a closed or soft-closed period: its due-total and its people's carried figures are live again, the current figures of the claims
     * due by a date inside it. Refused unless the sheet's permission matrix allows the user's role (a steward, unless
     * set), and when the period is neither closed nor soft-closed.
     */
    @Transactional
    public Period reopen(String sheetId, String user, long periodId) {
        sheetRows.lockById(sheetId);
        Period period = periods.findByIdAndSheetId(periodId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period"));
        if (!access.allows(sheetId, user, Permission.REOPEN)) {
            throw new PeriodRefused("Your role may not reopen a period on this sheet.");
        }
        if (!period.isFixed()) {
            throw new PeriodRefused("The period is not closed.");
        }
        period.reopen();
        periods.flush();
        events.publishEvent(new PeriodReopened(sheetId, user, period.getName()));
        return period;
    }

    /** The closed period whose dates contain the date, if any. */
    @Transactional(readOnly = true)
    public Optional<Period> closedOn(String sheetId, LocalDate date) {
        return list(sheetId).stream().filter(p -> p.isClosed() && p.contains(date)).findFirst();
    }

    /** The soft-closed period whose dates contain the date, if any. */
    @Transactional(readOnly = true)
    public Optional<Period> softClosedOn(String sheetId, LocalDate date) {
        return list(sheetId).stream().filter(p -> p.isSoftClosed() && p.contains(date)).findFirst();
    }

    /**
     * Refuse a change to a claim due by any of the dates when a closed period contains it. Holds the
     * sheet's lock until the transaction ends, so a period cannot close while the change is made.
     */
    @Transactional
    public void requireOpen(String sheetId, LocalDate... dates) {
        sheetRows.lockById(sheetId);
        for (LocalDate date : dates) {
            closedOn(sheetId, date).ifPresent(p -> {
                throw new ClosedPeriodRefused(p.getName());
            });
        }
    }
}

